def transforms(shape):
 ss=[]
 for flip in [False,True]:
  for k in range(4):
   pts=[]
   for r,c in shape:
    if flip: c=-c
    for _ in range(k): r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts); mc=min(c for r,c in pts)
   s=frozenset((r-mr,c-mc) for r,c in pts)
   if s not in ss: ss.append(s)
 return ss
def find(a,seedval):
 shape=np.argwhere(a==seedval); out=np.zeros(a.shape,bool); matches=[]
 for sh in transforms(shape):
  H=max(r for r,c in sh)+1;W=max(c for r,c in sh)+1
  for r in range(a.shape[0]-H+1):
   for c in range(a.shape[1]-W+1):
    pts=[(r+dr,c+dc) for dr,dc in sh]
    if all(a[x,y]==0 for x,y in pts):
     matches.append((sh,r,c));
     for x,y in pts: out[x,y]=True
 return out,matches
